Write-Host 'Ajout du choix de quantite avant ajout au panier...' -ForegroundColor Cyan
Write-FileFromBase64 -RelativePath "components/add-to-cart-button.tsx" -Base64Content $b64_0
Write-FileFromBase64 -RelativePath "components/product-purchase-actions.tsx" -Base64Content $b64_1
Write-FileFromBase64 -RelativePath "components/order-form.tsx" -Base64Content $b64_2

Write-Host ""
Write-Host "Modifications appliquees avec succes !" -ForegroundColor Green
Write-Host "Sur la fiche produit, le client choisit maintenant la quantite AVANT de cliquer sur Ajouter au panier." -ForegroundColor Green
Write-Host ""
$confirm = Read-Host "Voulez-vous faire git add / commit / push maintenant ? (o/n)"
if ($confirm -eq 'o' -or $confirm -eq 'O') {
    git add components/add-to-cart-button.tsx components/product-purchase-actions.tsx components/order-form.tsx
    git commit -m "Feat: permet de choisir la quantite sur la fiche produit avant d'ajouter au panier"
    git push
    Write-Host "Pousse sur Git avec succes !" -ForegroundColor Green
} else {
    Write-Host "Pas de push. Vous pouvez le faire plus tard avec : git add . ; git commit -m '...' ; git push" -ForegroundColor Yellow
}
